while len(text) > cols:
    end = text.rfind(' ', 0, cols + 1)
    if end == -1:
        end = cols
    line, text = text[:end], text[end:].lstrip()
    lines.append(line)

    # Handle the case when the last word is longer than the column width
    if len(text) > cols:
        lines.append(text)
        text = ''
